/*
 * Logos embedded as base64 data URIs.
 *
 * html2canvas taints the canvas (and toDataURL/download then fails) when the
 * logo is loaded cross-origin — which includes plain file:// URLs. Inlining
 * the PNGs as data URIs keeps the canvas clean so the app works whether it is
 * opened from disk (file://) or served over http.
 *
 * Source files: assets/img/logo-white.png and assets/img/logo-black.png.
 * If you change those PNGs, regenerate this file.
 */
const LOGO_DATA_URI = {
  white: "data:image/png;base64,",
  black: "data:image/png;base64,",
};